/**
 * @file src/ui/mobile.ts
 * Mobile layout (panneaux Combat / Équipe / Extras)
 */

import type { MobilePanelName } from './uiTypes.ts';
import { isMobileViewport } from './breakpoints.ts';
import { refreshTabsContainerScrollStates } from './navigation.ts';
import { initMobileScrollGate } from '../lib/mobileScrollGate.ts';
import { syncMobilePanelState } from '../stores/mobilePanel.svelte.ts';

export { isMobileViewport, MOBILE_MAX_WIDTH_PX, MOBILE_MEDIA_QUERY, MODAL_OPEN_SELECTOR } from './breakpoints.ts';

export const MOBILE_PANEL_CHANGED_EVENT = 'poketime:mobile-panel-changed' as const;

function notifyMobilePanelChanged(panelName: MobilePanelName): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new CustomEvent(MOBILE_PANEL_CHANGED_EVENT, { detail: panelName }));
}

/** Skip 60fps combat DOM render when another mobile panel is active. */
export function shouldSkipCombatRenderOnMobile(): boolean {
    if (!isMobileViewport()) return false;
    return !document.querySelector('.combat-area.mobile-active');
}

const panelScrollTops: Partial<Record<MobilePanelName, number>> = {};

function getPanelElement(panelName: MobilePanelName): HTMLElement | null {
    switch (panelName) {
        case 'combat':
            return document.querySelector('.combat-area');
        case 'team':
            return document.querySelector('.team-area');
        case 'extras':
            return document.getElementById('secondaryContent');
        default:
            return null;
    }
}

function getExtrasActiveTabScrollElement(): HTMLElement | null {
    const root = document.getElementById('secondaryContent');
    const activeTab = root?.querySelector(':scope > .tab-content.active');
    if (!(activeTab instanceof HTMLElement)) return null;
    if (activeTab.id === 'boutiqueTab') {
        const shopScroll = activeTab.querySelector('.sub-tab-content:not([hidden]) .shop-subtab-scroll');
        if (shopScroll instanceof HTMLElement && shopScroll.scrollHeight > shopScroll.clientHeight + 1) {
            return shopScroll;
        }
        return activeTab;
    }
    return activeTab;
}

export function getActiveMobilePanel(): MobilePanelName | null {
    if (document.querySelector('.combat-area.mobile-active')) return 'combat';
    if (document.querySelector('.team-area.mobile-active')) return 'team';
    if (document.querySelector('.secondary-content.mobile-active')) return 'extras';
    return null;
}

export function syncMobilePanelStateFromDom(): MobilePanelName | null {
    if (!isMobileViewport()) {
        syncMobilePanelState(null);
        return null;
    }
    const panel = getActiveMobilePanel() ?? 'combat';
    syncMobilePanelState(panel);
    return panel;
}

function saveActivePanelScroll(): void {
    for (const name of ['combat', 'team', 'extras'] as const) {
        const el = getPanelElement(name);
        if (!el?.classList.contains('mobile-active')) continue;
        if (name === 'extras') {
            const scrollEl = getExtrasActiveTabScrollElement();
            panelScrollTops[name] = scrollEl?.scrollTop ?? 0;
        } else {
            panelScrollTops[name] = el.scrollTop;
        }
        return;
    }
}

function updateMobileNavState(panelName: MobilePanelName): void {
    document.querySelectorAll('.mobile-nav-btn').forEach((btn) => {
        if (!(btn instanceof HTMLElement)) return;
        const isActive = btn.dataset.panel === panelName;
        btn.classList.toggle('active', isActive);
        if (isActive) {
            btn.setAttribute('aria-current', 'page');
        } else {
            btn.removeAttribute('aria-current');
        }
    });
}

type PanelTransitionDirection = 'left' | 'right' | 'none';

function flashPanelTransition(el: HTMLElement, direction: PanelTransitionDirection): void {
    if (direction === 'none') return;
    el.classList.remove('mobile-panel-from-left', 'mobile-panel-from-right');
    void el.offsetWidth;
    el.classList.add(direction === 'left' ? 'mobile-panel-from-right' : 'mobile-panel-from-left');
    window.setTimeout(() => {
        el.classList.remove('mobile-panel-from-left', 'mobile-panel-from-right');
    }, 240);
}

export function switchMobilePanel(panelName: string, transition: PanelTransitionDirection = 'none'): void {
    if (panelName !== 'combat' && panelName !== 'team' && panelName !== 'extras') return;
    if (!isMobileViewport()) return;

    saveActivePanelScroll();

    const combatArea = document.querySelector('.combat-area');
    const teamArea = document.querySelector('.team-area');
    const secondaryContent = document.getElementById('secondaryContent');

    [combatArea, teamArea, secondaryContent].forEach((el) => {
        if (el) el.classList.remove('mobile-active');
    });

    const target = getPanelElement(panelName);
    if (target) {
        target.classList.add('mobile-active');
        const saved = panelScrollTops[panelName];
        if (saved !== undefined) {
            if (panelName === 'extras') {
                const scrollEl = getExtrasActiveTabScrollElement();
                if (scrollEl) scrollEl.scrollTop = saved;
            } else {
                target.scrollTop = saved;
            }
        }
        flashPanelTransition(target, transition);
    }

    updateMobileNavState(panelName);
    syncMobilePanelState(panelName);
    notifyMobilePanelChanged(panelName);

    if (panelName === 'extras') {
        requestAnimationFrame(() => refreshTabsContainerScrollStates());
    }
}

export function initMobileLayout(): void {
    initMobileScrollGate();
    if (isMobileViewport()) {
        switchMobilePanel('combat');
        syncMobilePanelStateFromDom();
    }
}
